<?php use App\Support\App;$title='Sign in';require __DIR__.'/../layouts/head.php';?><main class="min-h-screen grid place-items-center p-6"><form id="auth" class="saas-card p-6 w-full max-w-sm space-y-4"><h1 class="text-2xl font-semibold">CEKSINYAL Login</h1><input type="hidden" name="_csrf" value="<?=App::csrf()?>"><input class="field" type="email" name="email" placeholder="Email" required><input class="field" type="password" name="password" placeholder="Password" required><button class="btn btn-dark w-full">Continue</button></form></main><script>auth.onsubmit=async e=>{e.preventDefault();let r=await fetch('/api/auth/login',{method:'POST',body:new FormData(auth)}),j=await r.json();j.ok?location.href=j.redirect:Swal.fire('Gagal',j.message,'error')}</script><?php require __DIR__.'/../layouts/foot.php';?>